package com.secure.documentwallet;

import android.app.*;
import android.content.*;
import android.graphics.*;
import android.os.Bundle;
import android.text.InputType;
import android.text.method.DigitsKeyListener;
import android.view.*;
import android.widget.*;
import androidx.fragment.app.FragmentActivity;
import org.json.*;
import java.text.*;
import java.util.*;
import java.util.concurrent.*;

/** Guided, private document-detail entry with OCR over already encrypted images. */
public class DocumentDetailsWizardActivity extends FragmentActivity {
 private final ExecutorService io=Executors.newSingleThreadExecutor();
 private VaultRepository repo;private JSONObject doc;private String group;private LinearLayout wizard;private TextView context;private Bitmap previewBitmap;private int stepGeneration;
 private static final int BLUE=0xff176de0;

 @Override public void onCreate(Bundle state){super.onCreate(state);Ui.safeScreen(this);Ui.lightBars(this);if(!Session.valid()){finish();return;}repo=new VaultRepository(this);build();load();}
 private void build(){LinearLayout page=VaultPageUi.page(this);page.addView(VaultPageUi.header(this,"Document Details","Private on-device wizard"));context=Ui.text(this,"Opening encrypted document…",12,Ui.MUTED);context.setPadding(Ui.dp(this,3),0,0,Ui.dp(this,10));page.addView(context);wizard=VaultPageUi.card(this);page.addView(wizard);setContentView(VaultPageUi.scroll(this,page));}
 private void load(){String id=getIntent().getStringExtra("id");io.execute(()->{try{doc=repo.get(id);if(doc==null)throw new IllegalStateException();group=DocumentGroups.fromCategory(doc.optString("category",getIntent().getStringExtra("group")));runOnUiThread(()->{context.setText(doc.optString("title","Document")+" · "+group);methodStep();});}catch(Exception e){runOnUiThread(()->{Ui.toast(this,"Could Not Open This Document");finish();});}});}

 private void begin(int step,String title,String subtitle){stepGeneration++;wizard.removeAllViews();clearPreview();LinearLayout progress=new LinearLayout(this);for(int i=1;i<=3;i++){View bar=new View(this);bar.setBackground(Ui.bg(i<=step?BLUE:Ui.BORDER,Ui.dp(this,4)));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,Ui.dp(this,5),1);if(i>1)p.leftMargin=Ui.dp(this,6);progress.addView(bar,p);}wizard.addView(progress);TextView heading=Ui.title(this,title,19);heading.setPadding(0,Ui.dp(this,16),0,Ui.dp(this,4));wizard.addView(heading);TextView note=Ui.text(this,subtitle,12,Ui.MUTED);note.setPadding(0,0,0,Ui.dp(this,14));wizard.addView(note);}
 private void methodStep(){begin(1,"How Would You Like To Add Details?","Choose a private OCR scan of this saved image or enter the details yourself.");if(!DocumentGroups.CERTIFICATES.equals(group))choice("scan","Scan Saved Image","Read labelled details from the encrypted image",this::ocrStep);choice("edit","Enter Manually",manualDescription(),this::manualStep);if(DocumentGroups.CERTIFICATES.equals(group)){TextView note=Ui.text(this,"Certificates use manual entry so their varied layouts remain unchanged.",11,Ui.MUTED);note.setPadding(Ui.dp(this,4),Ui.dp(this,5),Ui.dp(this,4),0);wizard.addView(note);}}
 private String manualDescription(){if(DocumentGroups.ID.equals(group))return "Issuer, number, issue date, and expiry date";if(DocumentGroups.CARDS.equals(group))return "Issuer, number, and month of expiry";return "Issuer, number, and issue date";}
 private void choice(String icon,String title,String detail,Runnable action){LinearLayout row=VaultPageUi.iconRow(this,icon,title,detail);row.setOnClickListener(v->action.run());VaultPageUi.addRow(wizard,row);}

 private void ocrStep(){if(DocumentGroups.ID.equals(group)){begin(2,"Which Saved Side Should I Read?","Choose the image containing the labelled details.");choice("id","Front","Driver's Permit · Issue Date · Expiry Date · Licence #",()->scanIdentity(true));choice("details","Back","National Identification Card · Date Of Issue · Expiry Date · Registration No",()->scanIdentity(false));back(this::methodStep);}else bankIssuerStep();}
 private void bankIssuerStep(){begin(2,"Name The Card Issuer","The saved card will then be scanned for Good Thru or Valid Thru.");EditText issuer=textField("Issuer Or Organization",doc.optString("issuer"));addField("Issuer Or Organization",issuer);buttonRow(this::methodStep,()->{String value=issuer.getText().toString().trim();if(value.isEmpty()){issuer.setError("Enter the card issuer");return;}scanBank(value);},"Scan Saved Card");}
 private void scanIdentity(boolean front){JSONArray pages=doc.optJSONArray("pages");int side=front?0:1;if(pages==null||side>=pages.length()){Ui.toast(this,front?"No Front Image Is Saved":"No Back Image Is Saved");return;}scan(side,front?"Reading Driver's Permit Labels…":"Reading Identification Card Labels…",(text,image)->reviewIdentity(DocumentDetailParser.identity(text,front),front,image));}
 private void scanBank(String issuer){JSONArray pages=doc.optJSONArray("pages");if(pages==null||pages.length()==0){Ui.toast(this,"No Card Image Is Saved");return;}scan(0,"Reading Good Thru Or Valid Thru…",(text,image)->reviewBank(DocumentDetailParser.bank(text,issuer),image));}
 private interface OcrResult{void ready(String text,byte[] image);}
 private void scan(int page,String message,OcrResult result){ProgressDialog wait=new ProgressDialog(this);wait.setCancelable(false);wait.setMessage(message);wait.show();io.execute(()->{try{byte[] image=repo.page(doc,page);String text=OcrIndexer.read(image);runOnUiThread(()->{wait.dismiss();result.ready(text,image);});}catch(Exception e){runOnUiThread(()->{wait.dismiss();Ui.toast(this,"The Saved Image Could Not Be Read. You Can Enter The Details Manually.");manualStep();});}});}

 private void reviewIdentity(JSONObject found,boolean front,byte[] image){begin(3,"Review The Scanned Details",front?"Front image scanned. Check any field OCR could not confidently read.":"Back image scanned. Check any field OCR could not confidently read.");addScannedPreview(image,front?"Scanned Front":"Scanned Back");EditText issuer=textField("Issuer Or Organization",found.optString("issuer")),number=numberField(found.optString("documentNumber")),issue=dateField(found.optString("issueDate"),false),expiry=dateField(found.optString("expiryDate"),false);addField("Issuer Or Organization",issuer);addField("Document Number",number);addField("Issue Date · DD/MM/YYYY",issue);addField("Expiry Date · DD/MM/YYYY",expiry);ocrStatus(found.optString("documentNumber").isEmpty()||found.optString("issueDate").isEmpty()||found.optString("expiryDate").isEmpty());buttonRow(this::ocrStep,()->save(issuer,number,issue,expiry),"Save Details");}
 private void reviewBank(JSONObject found,byte[] image){begin(3,"Review The Scanned Details","The card number and expiry are filled when OCR can verify them.");addScannedPreview(image,"Scanned Card");String scannedNumber=found.optString("documentNumber");if(scannedNumber.isEmpty())scannedNumber=doc.optString("documentNumber");EditText issuer=textField("Issuer Or Organization",found.optString("issuer")),number=numberField(scannedNumber),expiry=dateField(found.optString("expiryDate"),true,true);addField("Issuer Or Organization",issuer);addField("Document Number",number);addField("Expiry Date · MMMM/YYYY",expiry);ocrStatus(number.getText().toString().isEmpty()||found.optString("expiryDate").isEmpty());buttonRow(this::bankIssuerStep,()->save(issuer,number,null,expiry),"Save Details");}
 private void addScannedPreview(byte[] image,String label){BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(image,0,image.length,bounds);int sample=1;while(bounds.outWidth/sample>1400||bounds.outHeight/sample>1400)sample*=2;BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=sample;previewBitmap=BitmapFactory.decodeByteArray(image,0,image.length,options);if(previewBitmap==null)return;LinearLayout card=Ui.column(this);card.setPadding(Ui.dp(this,10),Ui.dp(this,9),Ui.dp(this,10),Ui.dp(this,10));card.setBackground(Ui.stroke(Ui.SOFT,Ui.dp(this,1),Ui.BORDER,Ui.dp(this,16)));TextView caption=Ui.text(this,label,11,Ui.MUTED);caption.setPadding(Ui.dp(this,2),0,0,Ui.dp(this,7));card.addView(caption);ImageView preview=new ImageView(this);preview.setAdjustViewBounds(true);preview.setScaleType(ImageView.ScaleType.FIT_CENTER);preview.setImageBitmap(previewBitmap);preview.setContentDescription(label+" Preview");card.addView(preview,new LinearLayout.LayoutParams(-1,Ui.dp(this,210)));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=Ui.dp(this,12);wizard.addView(card,p);}
 private void addManualPreview(){JSONArray pages=doc.optJSONArray("pages");if(pages==null||pages.length()==0)return;String label=DocumentGroups.CARDS.equals(group)?"Saved Card Front":DocumentGroups.ID.equals(group)?"Saved Front":"Saved Document";LinearLayout card=Ui.column(this);card.setPadding(Ui.dp(this,10),Ui.dp(this,9),Ui.dp(this,10),Ui.dp(this,10));card.setBackground(Ui.stroke(Ui.SOFT,Ui.dp(this,1),Ui.BORDER,Ui.dp(this,16)));TextView caption=Ui.text(this,label,11,Ui.MUTED);caption.setPadding(Ui.dp(this,2),0,0,Ui.dp(this,7));card.addView(caption);ProgressBar loading=new ProgressBar(this);card.addView(loading,new LinearLayout.LayoutParams(-1,Ui.dp(this,92)));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=Ui.dp(this,12);wizard.addView(card,p);int generation=stepGeneration;io.execute(()->{Bitmap bitmap=null;try{byte[] image=repo.page(doc,0);BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(image,0,image.length,bounds);int sample=1;while(bounds.outWidth/sample>1400||bounds.outHeight/sample>1400)sample*=2;BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=sample;bitmap=BitmapFactory.decodeByteArray(image,0,image.length,options);}catch(Exception ignored){}Bitmap ready=bitmap;runOnUiThread(()->{if(generation!=stepGeneration||isFinishing()){if(ready!=null)ready.recycle();return;}card.removeAllViews();card.addView(caption);if(ready==null){card.addView(Ui.text(this,"Preview Unavailable",12,Ui.MUTED));return;}previewBitmap=ready;ImageView preview=new ImageView(this);preview.setAdjustViewBounds(true);preview.setScaleType(ImageView.ScaleType.FIT_CENTER);preview.setImageBitmap(previewBitmap);preview.setContentDescription(label+" Preview");card.addView(preview,new LinearLayout.LayoutParams(-1,Ui.dp(this,210)));});});}
 private void clearPreview(){if(previewBitmap!=null&&!previewBitmap.isRecycled()){previewBitmap.recycle();previewBitmap=null;}}
 private void ocrStatus(boolean missing){LinearLayout status=VaultPageUi.notice(this,missing?"!":"✓",missing?"Review Required":"Details Found",missing?"One or more labels were not clear enough to fill automatically.":"OCR filled the labelled fields from the saved image.",missing?0xfffff3dc:0xffe4f6ef,missing?0xffb76a07:0xff168365);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=Ui.dp(this,5);wizard.addView(status,p);}

 private void manualStep(){begin(2,"Enter Document Details",manualDescription());addManualPreview();EditText issuer=textField("Issuer Or Organization",doc.optString("issuer")),number=numberField(doc.optString("documentNumber")),issue=null,expiry=null;addField("Issuer Or Organization",issuer);addField("Document Number",number);if(DocumentGroups.ID.equals(group)){issue=dateField(doc.optString("issueDate"),false);expiry=dateField(doc.optString("expiryDate"),false);addField("Issue Date · DD/MM/YYYY",issue);addField("Expiry Date · DD/MM/YYYY",expiry);}else if(DocumentGroups.CARDS.equals(group)){expiry=dateField(doc.optString("expiryDate"),true,false);addField("Expiry Date · MM/YYYY",expiry);}else{issue=dateField(doc.optString("issueDate"),false);addField("Issue Date · DD/MM/YYYY",issue);}EditText finalIssue=issue,finalExpiry=expiry;buttonRow(this::methodStep,()->save(issuer,number,finalIssue,finalExpiry),"Save Details");}
 private EditText textField(String hint,String value){EditText field=Ui.field(this,hint,false);field.setText(value==null?"":value);return field;}
 private EditText numberField(String value){EditText field=Ui.field(this,"Document Number",false);field.setInputType(InputType.TYPE_CLASS_NUMBER);field.setKeyListener(DigitsKeyListener.getInstance("0123456789"));field.setText(value==null?"":value.replaceAll("\\D",""));return field;}
 private EditText dateField(String value,boolean monthOnly){return dateField(value,monthOnly,true);}
 private EditText dateField(String value,boolean monthOnly,boolean namedMonth){EditText field=Ui.field(this,monthOnly?(namedMonth?"MMMM/YYYY":"MM/YYYY"):"DD/MM/YYYY",false);field.setText(value==null?"":value);field.setFocusable(false);field.setClickable(true);field.setCompoundDrawablesWithIntrinsicBounds(0,0,android.R.drawable.ic_menu_my_calendar,0);field.setCompoundDrawablePadding(Ui.dp(this,8));field.setOnClickListener(v->{if(monthOnly)pickMonth(field,namedMonth);else pickDate(field);});return field;}
 private void addField(String label,EditText field){TextView caption=Ui.text(this,label,12,Ui.MUTED);caption.setPadding(Ui.dp(this,2),Ui.dp(this,4),0,Ui.dp(this,5));wizard.addView(caption);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,Ui.dp(this,54));p.bottomMargin=Ui.dp(this,8);wizard.addView(field,p);}
 private void pickDate(EditText field){Calendar c=Calendar.getInstance();try{SimpleDateFormat f=new SimpleDateFormat("dd/MM/yyyy",Locale.US);f.setLenient(false);c.setTime(f.parse(field.getText().toString()));}catch(Exception ignored){}new DatePickerDialog(this,(view,year,month,day)->field.setText(String.format(Locale.US,"%02d/%02d/%04d",day,month+1,year)),c.get(Calendar.YEAR),c.get(Calendar.MONTH),c.get(Calendar.DAY_OF_MONTH)).show();}
 private void pickMonth(EditText field,boolean namedMonth){Calendar current=Calendar.getInstance();Date parsed=ExpiryUi.parse(field.getText().toString());if(parsed!=null)current.setTime(parsed);String[] months=Arrays.copyOf(new DateFormatSymbols(Locale.US).getMonths(),12);LinearLayout box=Ui.column(this);box.setPadding(Ui.dp(this,22),Ui.dp(this,8),Ui.dp(this,22),0);NumberPicker month=new NumberPicker(this),year=new NumberPicker(this);month.setMinValue(1);month.setMaxValue(12);month.setDisplayedValues(months);month.setValue(current.get(Calendar.MONTH)+1);year.setMinValue(1900);year.setMaxValue(current.get(Calendar.YEAR)+50);year.setValue(current.get(Calendar.YEAR));box.addView(month,new LinearLayout.LayoutParams(-1,Ui.dp(this,120)));box.addView(year,new LinearLayout.LayoutParams(-1,Ui.dp(this,120)));new AlertDialog.Builder(this).setTitle("Choose Expiry Month").setView(box).setNegativeButton("Cancel",null).setPositiveButton("Set",(d,w)->field.setText(namedMonth?months[month.getValue()-1]+"/"+year.getValue():String.format(Locale.US,"%02d/%04d",month.getValue(),year.getValue()))).show();}
 private void back(Runnable action){TextView button=VaultPageUi.secondary(this,"Back");button.setOnClickListener(v->action.run());LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,Ui.dp(this,48));p.topMargin=Ui.dp(this,6);wizard.addView(button,p);}
 private void buttonRow(Runnable previous,Runnable next,String nextLabel){LinearLayout row=new LinearLayout(this);TextView back=VaultPageUi.secondary(this,"Back"),save=VaultPageUi.primary(this,nextLabel);back.setOnClickListener(v->previous.run());save.setOnClickListener(v->next.run());LinearLayout.LayoutParams a=new LinearLayout.LayoutParams(0,Ui.dp(this,50),1),b=new LinearLayout.LayoutParams(0,Ui.dp(this,50),1.35f);b.leftMargin=Ui.dp(this,8);row.addView(back,a);row.addView(save,b);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=Ui.dp(this,10);wizard.addView(row,p);}
 private void save(EditText issuer,EditText number,EditText issue,EditText expiry){String a=issuer.getText().toString().trim(),b=number.getText().toString().trim(),c=issue==null?doc.optString("issueDate"):issue.getText().toString().trim(),d=expiry==null?doc.optString("expiryDate"):expiry.getText().toString().trim();if(a.isEmpty()){issuer.setError("Enter an issuer or organization");return;}io.execute(()->{try{repo.updateDetails(doc.getString("id"),a,b,c,d,doc.optString("tags"),doc.optString("notes"));doc.put("issuer",a).put("documentNumber",b).put("issueDate",c).put("expiryDate",d);ExpiryScheduler.schedule(this,doc);runOnUiThread(()->{setResult(RESULT_OK);Ui.toast(this,"Document Details Saved");finish();});}catch(Exception e){runOnUiThread(()->Ui.toast(this,"Could Not Save Document Details"));}});}
 @Override public boolean dispatchTouchEvent(android.view.MotionEvent event){if(Session.valid())Session.touch();return super.dispatchTouchEvent(event);}
 @Override protected void onDestroy(){clearPreview();super.onDestroy();io.shutdownNow();}
}
